class Table { constructor() { this.map = new Map(); this.headerDefined = false } }
class Arr { constructor(aot) { this.items = []; this.aot = aot } }
class Scalar { constructor(type, value) { this.type = type; this.value = value } }

class ParseError extends Error {}
const fail = (m) => { throw new ParseError(m) }

const isWs = (c) => c === ' ' || c === '\t'
const BARE = /^[A-Za-z0-9_-]$/

function walkTable(node, path, name) {
  // returns the table reached by stepping through `name` from `node`
  const cur = node.map.get(name)
  const p = [...path, name]
  if (cur === undefined) {
    const t = new Table()
    node.map.set(name, t)
    return [t, p]
  }
  if (cur instanceof Table) return [cur, p]
  if (cur instanceof Arr && cur.aot) return [cur.items[cur.items.length - 1], p]
  return fail(`${p.join('.')} is not a table`)
}

function assign(table, base, names, value) {
  let t = table
  let path = base
  for (let i = 0; i < names.length - 1; i++) [t, path] = walkTable(t, path, names[i])
  const last = names[names.length - 1]
  if (t.map.has(last)) fail(`key ${[...path, last].join('.')} is defined twice`)
  t.map.set(last, value)
}

