  constructor(s) { this.s = s; this.pos = 0 }
  eol() { const c = this.s[this.pos]; return c === undefined || c === '#' || c === ';' }
  skipWs() { while (isWs(this.s[this.pos])) this.pos++ }
  parseName() {
    const c = this.s[this.pos]
    if (c === '"') return this.basic()
    if (c === "'") return this.literal()
    let j = this.pos
    while (j < this.s.length && BARE.test(this.s[j])) j++
    if (j === this.pos) fail('expected a name')
    const r = this.s.slice(this.pos, j)
    this.pos = j
    return r
  }
  dotted() {
    const names = [this.parseName()]
    for (;;) {
      const save = this.pos
      this.skipWs()
      if (this.s[this.pos] === '.') {
        this.pos++
        this.skipWs()
        names.push(this.parseName())
      } else { this.pos = save; break }
    }
    return names
  }
  basic() {
    const s = this.s
    this.pos++
    let out = ''
    for (;;) {
      const c = s[this.pos]
      if (c === undefined) fail('unterminated string')
      if (c === '"') { this.pos++; return out }
      if (c === '\\') {
        const e = s[this.pos + 1]
        if (e === undefined) fail('unterminated string')
        const m = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
        if (Object.hasOwn(m, e)) { out += m[e]; this.pos += 2; continue }
        if (e === 'u') {
          const h = s.slice(this.pos + 2, this.pos + 6)
          if (!/^[0-9a-fA-F]{4}$/.test(h)) fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16))
          this.pos += 6
          continue
        }
        fail(`invalid escape \\${String.fromCodePoint(s.codePointAt(this.pos + 1))}`)
      }
      out += c
      this.pos++
    }
  }
  literal() {
    const j = this.s.indexOf("'", this.pos + 1)
    if (j < 0) fail('unterminated string')
    const r = this.s.slice(this.pos + 1, j)
    this.pos = j + 1
    return r
  }
  value(path) {
    const s = this.s
    const c = s[this.pos]
    if (c === undefined || c === ',' || c === ']' || c === '}' || c === '#' || c === ';') fail('expected a value')
    if (c === '"') return new Scalar('string', this.basic())
    if (c === "'") return new Scalar('string', this.literal())
    if (c === '[') return this.array(path)
    if (c === '{') return this.inline(path)
    let j = this.pos
    while (j < s.length && !isWs(s[j]) && !',]}'.includes(s[j])) j++
    const tok = s.slice(this.pos, j)
    this.pos = j
    if (tok === 'true' || tok === 'false') return new Scalar('boolean', tok === 'true')
    const D = '\\d+(?:_\\d+)*'
    if (new RegExp(`^[+-]?${D}$`).test(tok)) return new Scalar('integer', BigInt(tok.replace(/_/g, '')))
    if (new RegExp(`^[+-]?${D}(?:\\.${D})?(?:[eE][+-]?${D})?$`).test(tok)) {
      return new Scalar('float', Number(tok.replace(/_/g, '')))
    }
    return fail(`invalid value ${tok}`)
  }
  array(path) {
