    const a = new Arr(false)
    for (;;) {
      this.skipWs()
      if (this.eol()) fail('unterminated array')
      if (this.s[this.pos] === ']') { this.pos++; return a }
      a.items.push(this.value(path))
      this.skipWs()
      if (this.eol()) fail('unterminated array')
      const c = this.s[this.pos]
