    if (this.eol()) fail('unterminated inline table')
    if (this.s[this.pos] === '}') { this.pos++; return t }
    for (;;) {
      this.skipWs()
      if (this.eol()) fail('unterminated inline table')
      const names = this.dotted()
      this.skipWs()
      if (this.s[this.pos] !== '=') fail('expected = in an inline table')
      this.pos++
