  return JSON.stringify(node.value)
}

function typeOf(n) {
  return n instanceof Table ? 'table' : n instanceof Arr ? 'array' : n.type
}

function keyLines(node, path, out) {
  if (node instanceof Table) {
    for (const k of sortedKeys(node)) {
      const c = node.map.get(k)
      const p = path === null ? k : `${path}.${k}`
      out.push(`${p} ${typeOf(c)}`)
      keyLines(c, p, out)
    }
  } else if (node instanceof Arr) {
    node.items.forEach((c, i) => {
      const p = `${path}[${i}]`
      out.push(`${p} ${typeOf(c)}`)
      keyLines(c, p, out)
    })
  }
