    if (new RegExp(`^[+-]?${D}$`).test(tok)) return new Scalar('integer', BigInt(tok.replace(/_/g, '')))
    if (new RegExp(`^[+-]?${D}(?:\\.${D})?(?:[eE][+-]?${D})?$`).test(tok)) {
      return new Scalar('float', Number(tok.replace(/_/g, '')))
    }
    return fail(`invalid value ${tok}`)
  }
  array(path) {
    this.pos++
    const a = new Arr(false)
    for (;;) {
      this.skipWs()
      if (this.eol()) fail('unterminated array')
      if (this.s[this.pos] === ']') { this.pos++; return a }
      a.items.push(this.value(path))
      this.skipWs()
      if (this.eol()) fail('unterminated array')
      const c = this.s[this.pos]
      if (c === ',') this.pos++
      else if (c === ']') { this.pos++; return a }
      else fail('unterminated array')
    }
  }
  inline(path) {
    this.pos++
    const t = new Table()
    this.skipWs()
    if (this.eol()) fail('unterminated inline table')
    if (this.s[this.pos] === '}') { this.pos++; return t }
    for (;;) {
      this.skipWs()
      if (this.eol()) fail('unterminated inline table')
      const names = this.dotted()
      this.skipWs()
      if (this.s[this.pos] !== '=') fail('expected = in an inline table')
      this.pos++
      this.skipWs()
      const v = this.value([...path, ...names])
      assign(t, path, names, v)
      this.skipWs()
      if (this.eol()) fail('unterminated inline table')
      const c = this.s[this.pos]
      if (c === ',') this.pos++
      else if (c === '}') { this.pos++; return t }
      else fail('unterminated inline table')
    }
  }
}

function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const root = new Table()
  let cur = root
  let curPath = []
  for (let n = 0; n < lines.length; n++) {
    try {
      const L = new Line(lines[n])
      L.skipWs()
      if (L.eol()) continue
      if (L.s[L.pos] === '[') {
        const dbl = L.s[L.pos + 1] === '['
        L.pos += dbl ? 2 : 1
        L.skipWs()
        const names = L.dotted()
        L.skipWs()
        if (dbl ? L.s.startsWith(']]', L.pos) : L.s[L.pos] === ']') L.pos += dbl ? 2 : 1
        else fail('unterminated table header')
        L.skipWs()
        if (!L.eol()) fail('trailing text after a table header')
        let t = root
        let path = []
        for (let i = 0; i < names.length - 1; i++) [t, path] = walkTable(t, path, names[i])
        const last = names[names.length - 1]
        const full = [...path, last]
        const ex = t.map.get(last)
        if (dbl) {
          if (ex === undefined) {
            const a = new Arr(true)
            t.map.set(last, a)
            cur = new Table()
            a.items.push(cur)
          } else if (ex instanceof Arr && ex.aot) {
            cur = new Table()
            ex.items.push(cur)
          } else fail(`${full.join('.')} is not an array of tables`)
        } else if (ex === undefined) {
          cur = new Table()
          cur.headerDefined = true
          t.map.set(last, cur)
        } else if (ex instanceof Table) {
          if (ex.headerDefined) fail(`table ${full.join('.')} is defined twice`)
          ex.headerDefined = true
          cur = ex
        } else fail(`${full.join('.')} is not a table`)
        curPath = full
        continue
      }
      const names = L.dotted()
      L.skipWs()
      if (L.s[L.pos] !== '=') fail('expected key = value')
      L.pos++
      L.skipWs()
      const v = L.value([...curPath, ...names])
      L.skipWs()
      if (!L.eol()) fail('trailing text after a value')
      assign(cur, curPath, names, v)
    } catch (e) {
      if (e instanceof ParseError) throw new ParseError(`line ${n + 1}: ${e.message}`)
      throw e
    }
  }
  return root
}

function cmp(a, b) {
  let i = 0
  let j = 0
  while (i < a.length && j < b.length) {
    const x = a.codePointAt(i)
    const y = b.codePointAt(j)
    if (x !== y) return x < y ? -1 : 1
    i += x > 0xffff ? 2 : 1
    j += y > 0xffff ? 2 : 1
  }
  const ra = a.length - i
  const rb = b.length - j
  return ra < rb ? -1 : ra > rb ? 1 : 0
}
const sortedKeys = (t) => [...t.map.keys()].sort(cmp)

function toJson(node, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  if (node instanceof Table) {
    const ks = sortedKeys(node)
    if (!ks.length) return '{}'
    return '{\n' + ks.map((k) => `${pad}${JSON.stringify(k)}: ${toJson(node.map.get(k), ind + 1)}`).join(',\n') + '\n' + end + '}'
  }
  if (node instanceof Arr) {
    if (!node.items.length) return '[]'
    return '[\n' + node.items.map((x) => pad + toJson(x, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  if (node.type === 'integer') return node.value.toString()
  return JSON.stringify(node.value)
}

function typeOf(n) {
  return n instanceof Table ? 'table' : n instanceof Arr ? 'array' : n.type
}

function keyLines(node, path, out) {
  if (node instanceof Table) {
    for (const k of sortedKeys(node)) {
      const c = node.map.get(k)
      const p = path === null ? k : `${path}.${k}`
      out.push(`${p} ${typeOf(c)}`)
      keyLines(c, p, out)
    }
  } else if (node instanceof Arr) {
    node.items.forEach((c, i) => {
      const p = `${path}[${i}]`
      out.push(`${p} ${typeOf(c)}`)
      keyLines(c, p, out)
    })
  }
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'json' && args[0] !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}
let doc
try {
  doc = parse(readFileSync(0, 'utf8'))
} catch (e) {
  if (!(e instanceof ParseError)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
if (args[0] === 'json') process.stdout.write(toJson(doc, 0) + '\n')
else {
  const out = []
  keyLines(doc, null, out)
  process.stdout.write(out.map((l) => l + '\n').join(''))
}
